insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-748','6-38',748,'果断','guǒ duàn','quyết đoán, quả quyết','他果断地做出了决定。','Tā guǒduàn de zuòchū le juédìng.','Anh ấy đã quyết định một cách quả quyết.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-749','6-38',749,'过度','guò dù','quá mức, quá độ','我们需要控制过度消费。','Wǒmen xūyào kòngzhì guòdù xiāofèi.','Chúng ta cần kiểm soát việc tiêu thụ quá mức.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-750','6-38',750,'过渡','guò dù','chuyển tiếp, quá độ','我们需要一个平稳的过渡期。','Wǒmen xūyào yī gè píngwěn de guòdù qī.','Chúng ta cần một giai đoạn chuyển tiếp ổn định.');
