insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-752','6-38',752,'过滤','guò lǜ','lọc, sàng lọc','这个过滤器能有效去除水中的杂质。','Zhège guòlǜ qì néng yǒuxiào qùchú shuǐ zhōng de zázhì.','Bộ lọc này có thể loại bỏ tạp chất trong nước một cách hiệu quả.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-753','6-38',753,'过失','guò shī','lỗi lầm, sai lầm','他因为一次小小的过失被解雇了。','Tā yīnwèi yī cì xiǎoxiǎo de guòshī bèi jiěgù le.','Anh ấy bị sa thải vì một sai sót nhỏ.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-754','6-38',754,'过问','guò wèn','can thiệp, hỏi han','他对公司的事务一概不过问。','Tā duì gōngsī de shìwù yī gài bù guòwèn.','Anh ấy hoàn toàn không hỏi han gì về các công việc của công ty.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-755','6-38',755,'过瘾','guò yǐn','đã, sướng, thoả thích','这部电影真是让人看得过瘾。','Zhè bù diànyǐng zhēn shì ràng rén kàn de guòyǐn.','Bộ phim này thực sự khiến người xem đã mắt.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-756','6-38',756,'过于','guò yú','quá, hơn','这件衣服过于紧了。','Zhè jiàn yīfú guòyú jǐn le.','Chiếc áo này quá chật.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-757','6-38',757,'嗨','hāi','chào, này','嗨，大家好！','Hāi, dàjiā hǎo!','Chào mọi người!');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-758','6-38',758,'海拔','hǎi bá','độ cao so với mặt biển','这个山峰的海拔有三千米。','Zhège shānfēng de hǎibá yǒu sānqiān mǐ.','Đỉnh núi này cao ba nghìn mét so với mực nước biển.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-759','6-38',759,'海滨','hǎi bīn','bờ biển','我们在海滨度假。','Wǒmen zài hǎibīn dùjià.','Chúng tôi đi nghỉ mát ở bờ biển.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-760','6-38',760,'含糊','hán hu','mơ hồ, không rõ ràng','他的回答非常含糊。','Tā de huídá fēicháng hánhú.','Câu trả lời của anh ấy rất mơ hồ.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-761','6-39',761,'寒暄','hán xuān','hỏi han, trò chuyện','寒暄几句后，他们开始谈正事。','Hánxuān jǐ jù hòu, tāmen kāishǐ tán zhèngshì.','Sau vài câu xã giao, họ bắt đầu nói chuyện chính.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-762','6-39',762,'含义','hán yì','hàm ý, ý nghĩa','这个词的含义是什么？','Zhège cí de hányì shì shénme?','Nghĩa của từ này là gì?');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-763','6-39',763,'罕见','hǎn jiàn','hiếm thấy, hiếm gặp','这种病非常罕见。','Zhè zhǒng bìng fēicháng hǎnjiàn.','Bệnh này rất hiếm gặp.');
