insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-769','6-39',769,'豪迈','háo mài','hào hiệp, hào phóng','他豪迈地接受了挑战。','Tā háomài de jiēshòu le tiǎozhàn.','Anh ấy dũng cảm chấp nhận thử thách.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-770','6-39',770,'毫米','háo mǐ','milimét','这个零件的尺寸是10毫米。','Zhège língjiàn de chǐcùn shì 10 háomǐ.','Kích thước của bộ phận này là 10 mm.');
