insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-773','6-39',773,'好客','hào kè','hiếu khách','他是个非常好客的主人。','Tā shì gè fēicháng hàokè de zhǔrén.','Anh ấy là một chủ nhà rất hiếu khách.');
