insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-781','6-40',781,'和解','hé jiě','hòa giải','双方经过谈判终于和解了。','Shuāngfāng jīngguò tánpàn zhōngyú héjiě le.','Hai bên đã hòa giải sau khi đàm phán.');
