insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-786','6-40',786,'和谐','hé xié','hòa hợp, hài hòa','他们之间的关系非常和谐。','Tāmen zhī jiān de guānxì fēicháng héxié.','Mối quan hệ giữa họ rất hòa hợp.');
