insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-791','6-40',791,'哼','hēng','hừ, hừm','哼，我才不信呢！','Hēng, wǒ cái bù xìn ne!','Hừ, tôi không tin đâu!');
