insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-794','6-40',794,'轰动','hōng dòng','náo động, chấn động','这个消息在网上引起了轰动。','Zhège xiāoxi zài wǎngshàng yǐnqǐ le hōngdòng.','Tin tức này gây xôn xao trên mạng.');
