insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-796','6-40',796,'宏观','hóng guān','vĩ mô','他对宏观经济学非常感兴趣。','Tā duì hóngguān jīngjìxué fēicháng gǎn xìngqù.','Anh ấy rất quan tâm đến kinh tế vĩ mô.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-797','6-40',797,'洪水','hóng shuǐ','lũ lụt','大雨引发了洪水。','Dàyǔ yǐnfā le hóngshuǐ.','Mưa lớn gây ra lũ lụt.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-798','6-40',798,'宏伟','hóng wěi','hùng vĩ, to lớn','这座建筑宏伟壮观。','Zhè zuò jiànzhù hóngwěi zhuàngguān.','Tòa nhà này hùng vĩ tráng lệ.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-799','6-40',799,'喉咙','hóu lóng','cổ họng','他喉咙痛，声音沙哑。','Tā hóulóng tòng, shēngyīn shāyǎ.','Anh ấy bị đau họng và giọng khàn.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-800','6-40',800,'吼','hǒu','gào thét, hét lên','他吼了一声，表示不满。','Tā hǒu le yī shēng, biǎoshì bùmǎn.','Anh ấy hét lên một tiếng, biểu thị sự không hài lòng.');
