insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-802','6-41',802,'后顾之忧','hòu gù zhī yōu','lo lắng về sau','他的工作没有后顾之忧。','Tā de gōngzuò méiyǒu hòugùzhīyōu.','Công việc của anh ấy không có lo lắng về sau.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-803','6-41',803,'后面','hòu miàn','phía sau, đằng sau','她站在我后面。','Tā zhàn zài wǒ hòumiàn.','Cô ấy đứng sau tôi.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-804','6-41',804,'后勤','hòu qín','hậu cần','后勤部门负责保障工作。','Hòuqín bùmén fùzé bǎozhàng gōngzuò.','Bộ phận hậu cần chịu trách nhiệm đảm bảo công việc.');
