insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-862','6-44',862,'机关','jī guān','cơ quan, bộ máy','他在政府机关工作。','Tā zài zhèngfǔ jīguān gōngzuò.','Anh ấy làm việc trong cơ quan chính phủ.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-863','6-44',863,'基金','jī jīn','quỹ, ngân quỹ','我们需要更多的基金来支持这个项目。','Wǒmen xūyào gèng duō de jījīn lái zhīchí zhège xiàngmù.','Chúng tôi cần nhiều quỹ hơn để hỗ trợ dự án này.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-864','6-44',864,'激励','jī lì','khuyến khích, động viên','他的成功激励了我。','Tā de chénggōng jīlì le wǒ.','Sự thành công của anh ấy đã khích lệ tôi.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-865','6-44',865,'机灵','jī ling','lanh lợi, tinh nhanh','他是一个机灵的孩子。','Tā shì yī gè jīlíng de háizi.','Cậu bé là một đứa trẻ lanh lợi.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-866','6-44',866,'机密','jī mì','bí mật, cơ mật','这个文件是机密的。','Zhège wénjiàn shì jīmì de.','Tài liệu này là bí mật.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-867','6-44',867,'激情','jī qíng','nhiệt tình, hăng hái','他的激情感染了所有人。','Tā de jīqíng gǎnrǎn le suǒyǒu rén.','Nhiệt huyết của anh ấy đã lan tỏa đến mọi người.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-868','6-44',868,'讥笑','jī xiào','châm chọc, chế giễu','他的话让大家讥笑。','Tā de huà ràng dàjiā jīxiào.','Lời nói của anh ấy khiến mọi người cười nhạo.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-869','6-44',869,'机械','jī xiè','máy móc, cơ giới','这台机器操作简单。','Zhè tái jīqì cāozuò jiǎndān.','Cỗ máy này vận hành đơn giản.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-870','6-44',870,'基因','jī yīn','gen, di truyền','基因决定了我们的外貌。','Jīyīn juédìng le wǒmen de wàimào.','Gen quyết định ngoại hình của chúng ta.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-871','6-44',871,'机遇','jī yù','cơ hội','这次会议给了我们很多机遇。','Zhè cì huìyì gěi le wǒmen hěn duō jīyù.','Cuộc họp này đã mang lại nhiều cơ hội cho chúng tôi.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-872','6-44',872,'机智','jī zhì','lanh trí, tinh khôn','他回答问题非常机智。','Tā huídá wèntí fēicháng jīzhì.','Anh ấy trả lời câu hỏi rất thông minh.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-873','6-44',873,'即便','jí biàn','dù cho, cho dù','即便你不同意，也请听我说完。','Jíbiàn nǐ bù tóngyì, yě qǐng tīng wǒ shuō wán.','Dù bạn không đồng ý, cũng xin hãy nghe tôi nói hết.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-874','6-44',874,'级别','jí bié','cấp bậc, cấp độ','他在公司里的级别很高。','Tā zài gōngsī lǐ de jíbié hěn gāo.','Anh ấy có cấp bậc cao trong công ty.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-875','6-44',875,'疾病','jí bìng','bệnh tật, ốm đau','这种疾病很难治愈。','Zhè zhǒng jíbìng hěn nán zhìyù.','Bệnh này rất khó chữa.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-876','6-44',876,'嫉妒','jí dù','đố kỵ, ghen tị','她总是嫉妒别人的成功。','Tā zǒng shì jídù biéren de chénggōng.','Cô ấy luôn ghen tị với thành công của người khác.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-877','6-44',877,'极端','jí duān','cực đoan','他的看法太极端了。','Tā de kànfǎ tài jíduān le.','Quan điểm của anh ấy quá cực đoan.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-878','6-44',878,'急功近利','jí gōng jìn lì','vội vàng, nôn nóng','这种做法太急功近利了。','Zhè zhǒng zuòfǎ tài jígōngjìnlì le.','Cách làm này quá tham lợi trước mắt.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-879','6-44',879,'籍贯','jí guàn','quê quán','我的籍贯是北京。','Wǒ de jíguàn shì Běijīng.','Quê quán của tôi là Bắc Kinh.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-880','6-44',880,'即将','jí jiāng','sắp sửa, sắp tới','比赛即将开始。','Bǐsài jíjiāng kāishǐ.','Trận đấu sắp bắt đầu.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-881','6-45',881,'急剧','jí jù','nhanh chóng, mãnh liệt','气温急剧下降。','Qìwēn jíjù xiàjiàng.','Nhiệt độ giảm đột ngột.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-882','6-45',882,'急切','jí qiè','cấp thiết, khẩn cấp','他急切地想知道答案。','Tā jíqiè de xiǎng zhīdào dá''àn.','Anh ấy nóng lòng muốn biết câu trả lời.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-883','6-45',883,'集团','jí tuán','tập đoàn','这个集团在国际市场上非常有影响力。','Zhège jítuán zài guójì shìchǎng shàng fēicháng yǒu yǐngxiǎnglì.','Tập đoàn này có ảnh hưởng lớn trên thị trường quốc tế.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-884','6-45',884,'极限','jí xiàn','cực hạn, giới hạn','他挑战了极限。','Tā tiǎozhàn le jíxiàn.','Anh ấy đã thách thức giới hạn.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-885','6-45',885,'吉祥','jí xiáng','cát tường, may mắn','这个符号象征着吉祥。','Zhège fúhào xiàngzhēngzhe jíxiáng.','Biểu tượng này đại diện cho sự may mắn.');
