insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-887','6-45',887,'及早','jí zǎo','sớm, trước','我们需要及早完成任务。','Wǒmen xūyào jízǎo wánchéng rènwù.','Chúng ta cần hoàn thành nhiệm vụ sớm.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-888','6-45',888,'急躁','jí zào','nóng nảy, vội vàng','他太急躁了，做事总是三分钟热度。','Tā tài jízào le, zuò shì zǒng shì sān fēnzhōng rèdù.','Anh ấy quá nóng nảy, làm việc lúc nào cũng chỉ nhiệt tình được ba phút.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-889','6-45',889,'给予','jǐ yǔ','cho, tặng','我们应该给予他更多的支持。','Wǒmen yīnggāi jǐyǔ tā gèng duō de zhīchí.','Chúng ta nên ủng hộ anh ấy nhiều hơn.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-890','6-45',890,'继承','jì chéng','kế thừa','他继承了父亲的公司。','Tā jìchéng le fùqīn de gōngsī.','Anh ấy thừa kế công ty của cha mình.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-891','6-45',891,'季度','jì dù','quý (3 tháng)','每个季度我们都会有一次总结会议。','Měi gè jìdù wǒmen dōu huì yǒu yīcì zǒngjié huìyì.','Mỗi quý chúng tôi đều có một cuộc họp tổng kết.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-892','6-45',892,'忌讳','jì huì','kiêng kỵ','这个话题在公司里是忌讳的。','Zhège huàtí zài gōngsī lǐ shì jìhuì de.','Chủ đề này là điều cấm kỵ trong công ty.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-893','6-45',893,'计较','jì jiào','tính toán, so đo','他总是计较小事。','Tā zǒng shì jìjiào xiǎo shì.','Anh ấy luôn so đo những việc nhỏ nhặt.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-894','6-45',894,'寂静','jì jìng','yên tĩnh, tĩnh mịch','夜晚的森林非常寂静。','Yèwǎn de sēnlín fēicháng jìjìng.','Khu rừng vào ban đêm rất yên tĩnh.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-895','6-45',895,'季军','jì jūn','hạng ba, giải ba','他在比赛中获得了季军。','Tā zài bǐsài zhōng huòdé le jìjūn.','Anh ấy đạt giải ba trong cuộc thi.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-896','6-45',896,'技能','jì néng','kỹ năng','他在计算机方面有很高的技能。','Tā zài jìsuànjī fāngmiàn yǒu hěn gāo de jìnéng.','Anh ấy có kỹ năng cao trong lĩnh vực máy tính.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-897','6-45',897,'技巧','jì qiǎo','kỹ xảo, khéo léo','他的讲话技巧非常好。','Tā de jiǎnghuà jìqiǎo fēicháng hǎo.','Kỹ năng nói của anh ấy rất tốt.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-898','6-45',898,'寄托','jì tuō','gửi gắm, nhờ cậy','我把希望寄托在你身上。','Wǒ bǎ xīwàng jìtuō zài nǐ shēnshang.','Tôi đặt hy vọng vào bạn.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-899','6-45',899,'继往开来','jì wǎng kāi lái','tiếp nối phát triển','我们要继往开来，继续努力。','Wǒmen yào jìwǎngkāilái, jìxù nǔlì.','Chúng ta phải kế thừa và phát triển, tiếp tục nỗ lực.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-900','6-45',900,'迹象','jì xiàng','dấu hiệu, dấu vết','这些迹象表明了经济正在好转。','Zhèxiē jìxiàng biǎomíngle jīngjì zhèngzài hǎozhuǎn.','Những dấu hiệu này cho thấy kinh tế đang cải thiện.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-901','6-46',901,'记性','jì xìng','trí nhớ','他的记性非常好，从来不忘记重要的事情。','Tā de jìxìng fēicháng hǎo, cónglái bù wàngjì zhòngyào de shìqíng.','Trí nhớ của anh ấy rất tốt, không bao giờ quên những việc quan trọng.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-902','6-46',902,'纪要','jì yào','tóm tắt, ghi chép','会议的纪要已经发给了所有参加者。','Huìyì de jìyào yǐjīng fā gěi le suǒyǒu cānjiāzhě.','Biên bản cuộc họp đã được gửi đến tất cả người tham gia.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-903','6-46',903,'记载','jì zǎi','ghi chép, ghi lại','这个故事被详细地记载在书中。','Zhège gùshì bèi xiángxì de jìzǎi zài shū zhōng.','Câu chuyện này được ghi chép chi tiết trong sách.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-904','6-46',904,'家常','jiā cháng','thường ngày','这道菜是我们家常的做法。','Zhè dào cài shì wǒmen jiācháng de zuòfǎ.','Món ăn này là cách nấu thường ngày của nhà chúng tôi.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-905','6-46',905,'加工','jiā gōng','gia công, chế biến','这个产品需要经过精细的加工。','Zhège chǎnpǐn xūyào jīngguò jīngxì de jiāgōng.','Sản phẩm này cần qua gia công tỉ mỉ.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-906','6-46',906,'家伙','jiā huǒ','dụng cụ, khí cụ','他是个非常聪明的家伙。','Tā shì gè fēicháng cōngmíng de jiāhuo.','Anh ấy là một người rất thông minh.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-907','6-46',907,'加剧','jiā jù','trầm trọng thêm','经济问题的加剧让人们感到不安。','Jīngjì wèntí de jiājù ràng rénmen gǎndào bù''ān.','Sự gia tăng của các vấn đề kinh tế làm mọi người cảm thấy bất an.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-908','6-46',908,'家属','jiā shǔ','gia thuộc, người nhà','他是军人的家属，享有特别的待遇。','Tā shì jūnrén de jiāshǔ, xiǎngyǒu tèbié de dàiyù.','Anh ấy là người thân của quân nhân, được hưởng chế độ đãi ngộ đặc biệt.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-909','6-46',909,'佳肴','jiā yáo','món ngon, món ngon miệng','这顿佳肴真是美味无比。','Zhè dùn jiāyáo zhēnshì měiwèi wúbǐ.','Món ăn này thực sự rất ngon.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-910','6-46',910,'家喻户晓','jiā yù hù xiǎo','ai cũng biết, khắp nơi đều biết','这位演员已经是家喻户晓的明星。','Zhè wèi yǎnyuán yǐjīng shì jiāyùhùxiǎo de míngxīng.','Diễn viên này đã là ngôi sao nổi tiếng khắp nơi.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-911','6-46',911,'夹杂','jiā zá','xen lẫn, trộn lẫn','这些书夹杂着很多个人笔记。','Zhèxiē shū jiāzá zhe hěn duō gèrén bǐjì.','Những cuốn sách này xen lẫn nhiều ghi chép cá nhân.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-912','6-46',912,'假设','jiǎ shè','giả thiết, giả dụ','假设你是老板，你会怎么做？','Jiǎshè nǐ shì lǎobǎn, nǐ huì zěnme zuò?','Giả sử bạn là ông chủ, bạn sẽ làm gì?');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-913','6-46',913,'假使','jiǎ shǐ','nếu, giả sử','假使他知道了真相，他会非常生气。','Jiǎshǐ tā zhīdàole zhēnxiàng, tā huì fēicháng shēngqì.','Giả sử anh ta biết sự thật, anh ta sẽ rất tức giận.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-914','6-46',914,'坚定','jiān dìng','kiên định, vững chắc','他坚定地相信自己的选择。','Tā jiāndìng de xiāngxìn zìjǐ de xuǎnzé.','Anh ấy tin tưởng chắc chắn vào lựa chọn của mình.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-915','6-46',915,'监督','jiān dū','giám sát, quản lý','老师在监督学生们的考试。','Lǎoshī zài jiāndū xuéshēngmen de kǎoshì.','Giáo viên đang giám sát kỳ thi của các học sinh.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-916','6-46',916,'尖端','jiān duān','mũi nhọn, tiên tiến','科学家们正在研究尖端技术。','Kēxuéjiāmen zhèngzài yánjiū jiānduān jìshù.','Các nhà khoa học đang nghiên cứu công nghệ tiên tiến.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-917','6-46',917,'坚固','jiān gù','kiên cố, vững chắc','这个建筑非常坚固，能抗强风。','Zhège jiànzhú fēicháng jiāngù, néng kàng qiáng fēng.','Tòa nhà này rất kiên cố, có thể chịu được gió mạnh.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-918','6-46',918,'艰难','jiān nán','gian nan, khó khăn','他经历了很多艰难的时刻。','Tā jīnglìle hěn duō jiānnán de shíkè.','Anh ấy đã trải qua nhiều thời khắc khó khăn.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-919','6-46',919,'坚韧','jiān rèn','kiên cường, bền bỉ','她以坚韧的意志克服了困难。','Tā yǐ jiānrèn de yìzhì kèfú le kùnnán.','Cô ấy vượt qua khó khăn với ý chí kiên cường.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-920','6-46',920,'坚实','jiān shí','chắc chắn, vững chắc','这个计划非常坚实，值得信赖。','Zhège jìhuà fēicháng jiānshí, zhídé xìnlài.','Kế hoạch này rất vững chắc, đáng tin cậy.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-921','6-47',921,'监视','jiān shì','giám sát, theo dõi','警察在监视嫌疑人的一举一动。','Jǐngchá zài jiānshì xiányírén de yījǔyīdòng.','Cảnh sát đang giám sát mọi động tĩnh của nghi phạm.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-922','6-47',922,'坚硬','jiān yìng','cứng rắn, kiên cố','这种材料非常坚硬，适合建筑。','Zhè zhǒng cáiliào fēicháng jiānyìng, shìhé jiànzhú.','Loại vật liệu này rất cứng, phù hợp cho xây dựng.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-923','6-47',923,'监狱','jiān yù','nhà tù, trại giam','犯人被关在监狱里等待审判。','Fànrén bèi guān zài jiānyù lǐ děngdài shěnpàn.','Tội phạm bị giam trong nhà tù chờ xét xử.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-924','6-47',924,'兼职','jiān zhí','việc làm thêm, bán thời gian','他在学校里做兼职，赚取生活费。','Tā zài xuéxiào lǐ zuò jiānzhí, zhuàn qǔ shēnghuófèi.','Anh ấy làm thêm ở trường để kiếm tiền sinh hoạt.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-925','6-47',925,'拣','jiǎn','chọn, nhặt','我在花园里拣了几朵花。','Wǒ zài huāyuán lǐ jiǎn le jǐ duǒ huā.','Tôi đã nhặt vài bông hoa trong vườn.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-926','6-47',926,'剪彩','jiǎn cǎi','cắt băng khánh thành','今天的典礼上，他们为新图书馆剪彩。','Jīntiān de diǎnlǐ shàng, tāmen wèi xīn túshūguǎn jiǎncǎi.','Hôm nay, họ cắt băng khánh thành thư viện mới trong buổi lễ.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-927','6-47',927,'简化','jiǎn huà','giản hóa, đơn giản hóa','我们需要简化工作流程，提高效率。','Wǒmen xūyào jiǎnhuà gōngzuò liúchéng, tígāo xiàolǜ.','Chúng ta cần đơn giản hóa quy trình làm việc để nâng cao hiệu suất.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-928','6-47',928,'简陋','jiǎn lòu','sơ sài, thô sơ','这间房子简陋，但很温馨。','Zhè jiān fángzi jiǎnlòu, dàn hěn wēnxīn.','Ngôi nhà này tuy đơn sơ nhưng rất ấm cúng.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-929','6-47',929,'检讨','jiǎn tǎo','kiểm điểm, xem xét lại','我们会在会议上检讨这个计划。','Wǒmen huì zài huìyì shàng jiǎntǎo zhège jìhuà.','Chúng ta sẽ kiểm tra lại kế hoạch này trong cuộc họp.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-930','6-47',930,'简体字','jiǎn tǐ zì','chữ giản thể','简体字比繁体字更容易学习。','Jiǎntǐzì bǐ fántǐzì gèng róngyì xuéxí.','Chữ giản thể dễ học hơn chữ phồn thể.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-931','6-47',931,'检验','jiǎn yàn','kiểm nghiệm, kiểm tra','科学家正在检验新药的效果。','Kēxuéjiā zhèngzài jiǎnyàn xīnyào de xiàoguǒ.','Các nhà khoa học đang kiểm nghiệm hiệu quả của thuốc mới.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-932','6-47',932,'简要','jiǎn yào','tóm tắt, ngắn gọn','他简要地介绍了会议的主要内容。','Tā jiǎnyào de jièshào le huìyì de zhǔyào nèiróng.','Anh ấy tóm tắt nội dung chính của cuộc họp.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-933','6-47',933,'溅','jiàn','bắn lên, văng ra','水溅到了我的衣服上。','Shuǐ jiàn dào le wǒ de yīfú shàng.','Nước bắn lên quần áo của tôi.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-934','6-47',934,'鉴别','jiàn bié','phân biệt, nhận định','专家们正在鉴别这幅画的真伪。','Zhuānjiāmen zhèngzài jiànbié zhè fú huà de zhēnwěi.','Các chuyên gia đang xác định tính xác thực của bức tranh này.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-935','6-47',935,'间谍','jiàn dié','gián điệp','他是一个间谍，潜伏在敌人内部。','Tā shì yī gè jiàndié, qiánfú zài dírén nèibù.','Anh ta là một điệp viên, nằm vùng trong hàng ngũ địch.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-936','6-47',936,'鉴定','jiàn dìng','giám định, xác định','这栋建筑需要进行安全鉴定。','Zhè dòng jiànzhú xūyào jìnxíng ānquán jiàndìng.','Tòa nhà này cần được đánh giá an toàn.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-937','6-47',937,'见多识广','jiàn duō shí guǎng','hiểu biết rộng rãi','他是个见多识广的人，什么都知道。','Tā shì gè jiànduōshíguǎng de rén, shénme dōu zhīdào.','Anh ấy là một người hiểu biết rộng, cái gì cũng biết.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-938','6-47',938,'间隔','jiàn gé','khoảng cách, khoảng thời gian','两次会议之间有一个小时的间隔。','Liǎng cì huìyì zhījiān yǒu yī gè xiǎoshí de jiàngé.','Có một khoảng cách một giờ giữa hai cuộc họp.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-939','6-47',939,'间接','jiàn jiē','gián tiếp','我们通过间接证据推断出真相。','Wǒmen tōngguò jiànjiē zhèngjù tuīduàn chū zhēnxiàng.','Chúng tôi suy luận ra sự thật thông qua các chứng cứ gián tiếp.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-940','6-47',940,'见解','jiàn jiě','cách nhìn, quan điểm','他的见解很独特，值得参考。','Tā de jiànjiě hěn dútè, zhídé cānkǎo.','Quan điểm của anh ấy rất độc đáo, đáng để tham khảo.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-941','6-48',941,'健全','jiàn quán','kiện toàn, hoàn thiện','我们需要建立一个健全的制度。','Wǒmen xūyào jiànlì yī gè jiànquán de zhìdù.','Chúng ta cần thiết lập một hệ thống lành mạnh.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-942','6-48',942,'践踏','jiàn tà','dẫm đạp, đạp nát','他们肆意践踏法律，必须受到惩罚。','Tāmen sìyì jiàntà fǎlǜ, bìxū shòudào chéngfá.','Họ tự do chà đạp lên pháp luật, cần phải bị trừng phạt.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-943','6-48',943,'舰艇','jiàn tǐng','tàu chiến','这艘舰艇将在下个月服役。','Zhè sōu jiàntǐng jiàng zài xià gè yuè fúyì.','Con tàu chiến này sẽ vào biên chế vào tháng tới.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-944','6-48',944,'见闻','jiàn wén','hiểu biết, sự từng trải','他的见闻非常广泛，知识丰富。','Tā de jiànwén fēicháng guǎngfàn, zhīshì fēngfù.','Kiến thức của anh ấy rất rộng, hiểu biết phong phú.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-945','6-48',945,'见义勇为','jiàn yì yǒng wéi','thấy việc nghĩa thì làm','他见义勇为，救了很多人。','Tā jiànyìyǒngwéi, jiù le hěn duō rén.','Anh ấy dũng cảm làm việc nghĩa, cứu được nhiều người.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-946','6-48',946,'鉴于','jiàn yú','bởi vì, xét thấy','鉴于天气恶劣，我们决定取消旅行。','Jiànyú tiānqì èliè, wǒmen juédìng qǔxiāo lǚxíng.','Do thời tiết xấu, chúng tôi quyết định hủy bỏ chuyến đi.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-947','6-48',947,'将近','jiāng jìn','gần, xấp xỉ','他将近六十岁了，还在工作。','Tā jiāngjìn liùshí suì le, hái zài gōngzuò.','Anh ấy gần sáu mươi tuổi rồi, vẫn đang làm việc.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-948','6-48',948,'将军','jiāng jūn','tướng quân, tướng lĩnh','将军亲自指挥这次行动。','Jiāngjūn qīnzì zhǐhuī zhè cì xíngdòng.','Vị tướng đích thân chỉ huy hành động lần này.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-949','6-48',949,'僵硬','jiāng yìng','cứng đờ, không linh hoạt','他的手指冻得僵硬。','Tā de shǒuzhǐ dòng dé jiāngyìng.','Ngón tay của anh ấy bị lạnh đến cứng đờ.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-950','6-48',950,'桨','jiǎng','mái chèo','他划着一只小船，用桨轻轻划水。','Tā huá zhe yī zhī xiǎo chuán, yòng jiǎng qīng qīng huá shuǐ.','Anh ấy chèo một chiếc thuyền nhỏ, nhẹ nhàng dùng mái chèo để chèo nước.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-951','6-48',951,'奖励','jiǎng lì','khen thưởng, khuyến khích','老板奖励了他一笔奖金。','Lǎobǎn jiǎnglì le tā yī bǐ jiǎngjīn.','Ông chủ thưởng cho anh ấy một khoản tiền thưởng.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-952','6-48',952,'奖赏','jiǎng shǎng','thưởng, phần thưởng','他因表现出色而得到奖赏。','Tā yīn biǎoxiàn chūsè ér dédào jiǎngshǎng.','Anh ấy được thưởng vì biểu hiện xuất sắc.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-953','6-48',953,'降临','jiàng lín','đến, xảy đến','春天的到来让人们感到兴奋，降临在每个人的心中。','Chūntiān de dàolái ràng rénmen gǎndào xīngfèn, jiànglín zài měi gèrén de xīnzhōng.','Mùa xuân đến làm mọi người cảm thấy phấn khởi, đến trong lòng mỗi người.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-954','6-48',954,'交叉','jiāo chā','giao nhau, cắt ngang','这两条路在这里交叉。','Zhè liǎng tiáo lù zài zhèlǐ jiāochā.','Hai con đường này giao nhau tại đây.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-955','6-48',955,'交代','jiāo dài','giải thích, bàn giao','他向老板交代了工作进展情况。','Tā xiàng lǎobǎn jiāodài le gōngzuò jìnzhǎn qíngkuàng.','Anh ấy báo cáo tình hình tiến độ công việc với ông chủ.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-956','6-48',956,'焦点','jiāo diǎn','tiêu điểm, điểm nóng','我们要解决这个问题的焦点。','Wǒmen yào jiějué zhège wèntí de jiāodiǎn.','Chúng ta cần giải quyết trọng tâm của vấn đề này.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-957','6-48',957,'焦急','jiāo jí','lo lắng, sốt ruột','他的焦急心情显而易见。','Tā de jiāojí xīnqíng xiǎn''éryìjiàn.','Tâm trạng lo lắng của anh ấy rất rõ ràng.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-958','6-48',958,'娇气','jiāo qì','mềm yếu, mỏng manh','她的娇气让人受不了。','Tā de jiāoqì ràng rén shòubùliǎo.','Sự yếu đuối của cô ấy làm người khác không chịu nổi.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-959','6-48',959,'交涉','jiāo shè','đàm phán, thương lượng','我们正在和对方公司交涉合同细节。','Wǒmen zhèngzài hé duìfāng gōngsī jiāoshè hétóng xìjié.','Chúng tôi đang đàm phán chi tiết hợp đồng với công ty đối tác.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-960','6-48',960,'交往','jiāo wǎng','qua lại, giao lưu','他们之间的交往非常密切。','Tāmen zhījiān de jiāowǎng fēicháng mìqiè.','Quan hệ giữa họ rất thân thiết.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-961','6-49',961,'交易','jiāo yì','giao dịch, buôn bán','他们达成了一项重要的交易。','Tāmen dáchéngle yī xiàng zhòngyào de jiāoyì.','Họ đã đạt được một giao dịch quan trọng.');
